// Monta os dados públicos do portal/ranking: sem telefones e sem nomes de alunos
const rows = (node) => {
  try {
    return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length && !r.error);
  } catch {
    return [];
  }
};

const num = (v) => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').replace(/[^\d,.-]/g, '');
  if (!s) return 0;
  return s.includes(',') ? Number(s.replace(/\./g, '').replace(',', '.')) || 0 : Number(s) || 0;
};

// "09/11/2026 14:04:00" (horário de Brasília) -> ISO
const toISO = (v) => {
  const m = String(v ?? '').match(/^(\d{2})\/(\d{2})\/(\d{4})[ T](\d{2}):(\d{2})(?::(\d{2}))?/);
  if (m) return `${m[3]}-${m[2]}-${m[1]}T${m[4]}:${m[5]}:${m[6] || '00'}-03:00`;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
};

const personais = rows('Ler Personais')
  .filter((r) => r['ID'] && r['Nome'])
  .map((r) => {
    const ativo = String(r['Ativo'] ?? 'sim').toLowerCase();
    const foto = String(r['Foto'] ?? '');
    return {
      id: String(r['ID']),
      name: String(r['Nome']),
      firstName: String(r['Primeiro Nome'] || String(r['Nome']).split(' ')[0]),
      gym: String(r['Academia'] ?? ''),
      code: String(r['Cupom'] ?? ''),
      active: !['não', 'nao', 'false', '0'].includes(ativo),
      avatarUrl: foto.startsWith('data:image/') ? foto : undefined
    };
  });

const ids = new Set(personais.map((p) => p.id));

const sales = rows('Ler Vendas')
  .filter((r) => r['ID Venda'] && ids.has(String(r['Personal ID'])))
  .map((r) => ({
    id: String(r['ID Venda']),
    personalId: String(r['Personal ID']),
    personalName: String(r['Personal'] ?? ''),
    value: num(r['Valor (R$)']),
    pointsAdded: Math.round(num(r['Pontos'])),
    notes: String(r['Itens'] ?? ''),
    timestamp: toISO(r['Data/Hora'])
  }))
  .filter((s) => s.timestamp);

const cfg = new Map();
for (const r of rows('Ler Config')) {
  const k = String(r['Chave'] ?? '').trim();
  if (k) cfg.set(k, r['Valor'] ?? '');
}

let prizes;
if (cfg.has('prizes')) {
  try {
    const parsed = JSON.parse(String(cfg.get('prizes') || '{}'));
    if (parsed && typeof parsed === 'object') prizes = parsed;
  } catch {}
}

const settings = {};
if (cfg.has('whatsappTemplate') && String(cfg.get('whatsappTemplate') || '')) {
  settings.whatsappTemplate = String(cfg.get('whatsappTemplate'));
}
if (cfg.has('commissionRate') && String(cfg.get('commissionRate') ?? '') !== '') {
  const rate = num(cfg.get('commissionRate'));
  if (!isNaN(rate) && rate >= 0) settings.commissionRate = rate;
}
if (cfg.has('storeName') && String(cfg.get('storeName') || '').trim()) {
  settings.storeName = String(cfg.get('storeName')).trim();
}

const payload = { updatedAt: new Date().toISOString(), personais, sales };
if (prizes) payload.prizes = prizes;
if (Object.keys(settings).length > 0) payload.settings = settings;

return [{ json: payload }];
